package fr.elan.app.content

data class SketchPoint(val x: Float, val y: Float)
data class PoseSketch(val head: SketchPoint, val strokes: List<List<SketchPoint>>, val supports: List<List<SketchPoint>>)

object PoseSketches {
    private fun paths(value: String): List<List<SketchPoint>> = if (value.isBlank()) emptyList() else
        value.split("|").map { path -> path.split(" ").map { coordinate ->
            val xy = coordinate.split(","); SketchPoint(xy[0].toFloat(), xy[1].toFloat())
        } }
    private fun sketch(x: Float, y: Float, body: String, supports: String = "") = PoseSketch(SketchPoint(x, y), paths(body), paths(supports))
